//! 🧵️ Actual initialized allocations elect one owner and retain partial fields until funded release.
use super::*;
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use std::sync::atomic::AtomicUsize;
fn grant(d:crate::RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn storage<T:Send+Sync+'static>(value:T)->SharedOriginalStorage<T>{let mut source=Some(value);let mut target=None;let mut actual=None;let d=SharedOriginalStorage::<T>::source_admission_demand().unwrap();let turn=SharedOriginalStorage::admit_from(&mut source,&mut target,grant(d),&mut actual);turn.result.unwrap();assert!(source.is_none());assert_eq!(actual,Some(d.capacity_bytes));target.unwrap()}
fn duplicate<T:Send+Sync+'static>(source:&SharedOriginalStorage<T>)->SharedOriginalStorage<T>{source.duplicate(grant(SharedOriginalStorage::<T>::duplicate_demand())).result.unwrap()}
struct Probe(Arc<AtomicUsize>);
impl Drop for Probe{fn drop(&mut self){self.0.fetch_add(1,Ordering::SeqCst);}}
#[test]
fn concurrent_alias_retirement_elects_one_original_without_moving_or_dropping_it(){
 let drops=Arc::new(AtomicUsize::new(0));let storage=storage(Probe(Arc::clone(&drops)));let pointer=storage.identity();let peer=duplicate(&storage);let left=std::thread::spawn(move||storage.retire());let right=std::thread::spawn(move||peer.retire());let mut original=None;let mut aliases=0;for result in[left.join().unwrap(),right.join().unwrap()]{match result{SharedOriginalRelease::Alias=>aliases+=1,SharedOriginalRelease::Original(owner)=>{assert!(original.replace(owner).is_none());}}}assert_eq!(aliases,1);let mut owner=original.unwrap();assert_eq!(owner.identity(),pointer);assert_eq!(drops.load(Ordering::SeqCst),0);drop(owner.take_value().unwrap());assert_eq!(drops.load(Ordering::SeqCst),1);assert!(owner.terminal_is_empty());
}
#[test]
fn selected_field_retirement_retains_untouched_originals_and_funds_final_storage_release(){
 struct Pair{left:Probe,right:Probe}
 let drops=Arc::new(AtomicUsize::new(0));let(storage,heap)=observe(||storage(Pair{left:Probe(Arc::clone(&drops)),right:Probe(Arc::clone(&drops))}));assert_eq!(heap,(SharedOriginalStorage::<Pair>::allocation_bytes(),0));let pointer=storage.identity();let SharedOriginalRelease::Original(mut owner)=storage.retire()else{panic!("one original owner")};assert_eq!(owner.identity(),pointer);let failed:Result<(),_>=Err(owner);owner=failed.unwrap_err();assert_eq!(owner.identity(),pointer);assert_eq!(drops.load(Ordering::SeqCst),0);let left=unsafe{owner.take_field(|root|std::ptr::addr_of_mut!((*root).left))};drop(left);assert_eq!(drops.load(Ordering::SeqCst),1);let right=unsafe{owner.take_field(|root|std::ptr::addr_of_mut!((*root).right))};drop(right);assert_eq!(drops.load(Ordering::SeqCst),2);let below=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:SharedOriginal::<Pair>::allocation_bytes()-1,maximum_depth:1,..Default::default()};let(receipt,heap)=observe(||unsafe{owner.release_empty(below)});assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));assert!(!owner.terminal_is_empty());let issued=RetainedCloneGrant{maximum_release_bytes:SharedOriginal::<Pair>::allocation_bytes(),..below};let(receipt,heap)=observe(||unsafe{owner.release_empty(issued)});assert!(receipt.fits(issued));assert_eq!(heap,(0,receipt.released_bytes));assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));
}

#[test]
fn delayed_physical_alias_drop_cannot_free_initialized_or_unfunded_storage(){
 let storage=storage(7u64);let peer=duplicate(&storage);let delayed=Arc::clone(peer.source.as_ref().unwrap());assert!(matches!(peer.retire(),SharedOriginalRelease::Alias));let SharedOriginalRelease::Original(mut original)=storage.retire()else{panic!("one elected original")};assert!(!original.physical_is_unique());let issued=RetainedCloneGrant{maximum_items:1,maximum_release_bytes:SharedOriginal::<u64>::allocation_bytes(),maximum_depth:1,..Default::default()};let value=unsafe{original.take_field(|root|root)};assert_eq!(value,7);let(receipt,heap)=observe(||unsafe{original.release_empty(issued)});assert_eq!(receipt,Default::default());assert_eq!(heap,(0,0));let(_,heap)=observe(||drop(delayed));assert_eq!(heap,(0,0));assert!(original.physical_is_unique());let(receipt,heap)=observe(||unsafe{original.release_empty(issued)});assert_eq!(heap,(0,receipt.released_bytes));assert_eq!(receipt.released_bytes,SharedOriginal::<u64>::allocation_bytes());assert!(original.terminal_is_empty());
}

#[test]
fn original_shared_metadata_receipts_match_the_same_neutral_primitive_plan() {
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let d=SharedOriginalStorage::<u64>::prepare_birth_demand().unwrap();let mut actual=None;
 let(turn,heap)=observe(||SharedOriginalStorage::<u64>::prepare_birth(grant(d),&mut actual));assert_eq!(turn.work,u128::from(law["work"]["prepare"]["total"].as_u64().unwrap()));let(mut birth,p)=turn.result.unwrap();assert_eq!(heap,(d.capacity_bytes,0));assert_eq!(actual,Some(d.capacity_bytes));assert_eq!(p.copied_bytes,d.copy_bytes);
 let d=SharedOriginalBirth::<u64>::publication_demand();let token=birth.publication(grant(d)).unwrap().unwrap();let(turn,heap)=observe(||token.commit(73));assert_eq!(turn.work,u128::from(law["work"]["publication"]["total"].as_u64().unwrap()));assert_eq!(heap,(0,0));let(storage,p)=turn.result.unwrap();assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(*storage.get(),73);assert_eq!(storage.aliases(),1);
 let(turn,heap)=observe(||storage.duplicate(grant(SharedOriginalStorage::<u64>::duplicate_demand())));assert_eq!(turn.work,u128::from(law["work"]["duplicate"]["total"].as_u64().unwrap()));assert_eq!(heap,(0,0));let alias=turn.result.unwrap();assert_eq!(alias.identity(),storage.identity());assert_eq!(storage.aliases(),2);assert!(matches!(alias.retire(),SharedOriginalRelease::Alias));let SharedOriginalRelease::Original(mut owner)=storage.retire()else{panic!("unique original")};assert_eq!(owner.take_value(),Some(73));assert!(owner.terminal_is_empty());assert!(birth.terminal_is_empty());
}

#[test]fn original_election_and_whole_payload_handback_deny_every_unfunded_axis_without_effects(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut storage=storage(73u64);let pointer=storage.identity();let d=storage.retire_demand().unwrap();let q=storage.retire_work_demand().unwrap();assert_eq!(q,law["work"]["retireAlias"]["total"].as_u64().unwrap());
 for axis in 0..4{let mut g=grant(d);let maximum=if axis==3{q-1}else{q};match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=d.copy_bytes-1,2=>g.maximum_depth=0,_=>{}}let(turn,heap)=observe(||storage.retire_step(g,maximum));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(storage.identity(),pointer);assert_eq!(*storage.get(),73);assert_eq!(storage.aliases(),1);}
 let(turn,heap)=observe(||storage.retire_step(grant(d),q));assert_eq!(turn.work,u128::from(law["work"]["retireOriginal"]["total"].as_u64().unwrap()));assert_eq!(heap,(0,0));let(SharedOriginalRelease::Original(mut owner),p)=turn.result.unwrap().unwrap()else{panic!("unique original elected")};assert_eq!(p.copied_bytes,d.copy_bytes-std::mem::size_of::<AtomicUsize>());let d=owner.take_value_demand().unwrap();let q=owner.take_value_work_demand().unwrap();assert_eq!(q,law["work"]["takeValue"]["total"].as_u64().unwrap());
 for axis in 0..5{let mut g=grant(d);let maximum=if axis==4{q-1}else{q};match axis{0=>g.maximum_items=0,1=>g.maximum_copy_bytes=d.copy_bytes-1,2=>g.maximum_release_bytes=d.release_bytes-1,3=>g.maximum_depth=0,_=>{}}let(turn,heap)=observe(||owner.take_value_step(g,maximum));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(owner.identity(),pointer);assert_eq!(*owner.get(),73);}
 let delayed=Arc::clone(owner.source.as_ref().unwrap());let(turn,heap)=observe(||owner.take_value_step(grant(d),q));assert_eq!(turn.work,0);assert!(turn.result.unwrap().is_none());assert_eq!(heap,(0,0));assert_eq!(*owner.get(),73);assert_eq!(observe(||drop(delayed)).1,(0,0));let(turn,heap)=observe(||owner.take_value_step(grant(d),q));assert_eq!(turn.work,u128::from(q));let(value,p)=turn.result.unwrap().unwrap();assert_eq!(value,73);assert_eq!(p.copied_bytes,d.copy_bytes);assert_eq!(heap,(0,p.released_bytes));assert_eq!(p.released_bytes,d.release_bytes);assert!(p.fits(grant(d)));assert!(owner.terminal_is_empty());assert_eq!(owner.take_value_work_demand().unwrap(),0);let empty=owner.take_value_step(grant(Default::default()),0);assert_eq!(empty.work,0);assert!(empty.result.unwrap().is_none());
}
#[test]fn funded_concurrent_alias_election_reports_only_the_actual_selected_branch(){
 let storage=storage(73u64);let pointer=storage.identity();let peer=duplicate(&storage);let run=|mut value:SharedOriginalStorage<u64>|{let d=value.retire_demand().unwrap();let q=value.retire_work_demand().unwrap();let(turn,heap)=observe(||value.retire_step(grant(d),q));assert_eq!(heap,(0,0));let(output,p)=turn.result.unwrap().unwrap();let original=matches!(&output,SharedOriginalRelease::Original(_));assert_eq!(turn.work,if original{3}else{4});assert_eq!(p.copied_bytes,d.copy_bytes-if original{std::mem::size_of::<AtomicUsize>()}else{0});output};let left=std::thread::spawn(move||run(storage));let right=std::thread::spawn(move||run(peer));let mut owner=None;let mut aliases=0;for output in[left.join().unwrap(),right.join().unwrap()]{match output{SharedOriginalRelease::Alias=>aliases+=1,SharedOriginalRelease::Original(value)=>assert!(owner.replace(value).is_none())}}assert_eq!(aliases,1);let mut owner=owner.unwrap();assert_eq!(owner.identity(),pointer);let d=owner.take_value_demand().unwrap();let q=owner.take_value_work_demand().unwrap();let(turn,heap)=observe(||owner.take_value_step(grant(d),q));let(value,p)=turn.result.unwrap().unwrap();assert_eq!(value,73);assert_eq!(heap,(0,p.released_bytes));assert!(owner.terminal_is_empty());
}
